const catalog=[
{id:1,name:'Organizador de escritorio',department:'Hogar',price:18,stock:6,origin:'local'},
{id:2,name:'Soporte para teléfono',department:'Tecnología',price:15,stock:8,origin:'local'},
{id:3,name:'Collar geométrico',department:'Joyería',price:24,stock:4,origin:'local',variants:['Dorado','Plateado']},
{id:4,name:'Bolsa organizadora de viaje',department:'Viajes',price:22,stock:5,origin:'external'},
{id:5,name:'Dispensador para mascotas',department:'Mascotas',price:12,stock:0,origin:'local'},
{id:6,name:'Soporte para automóvil',department:'Automóvil',price:19,stock:7,origin:'external'},
{id:7,name:'Bandeja para accesorios',department:'Hogar',price:16,stock:5,origin:'local'},
{id:8,name:'Estuche de cables',department:'Tecnología',price:14,stock:3,origin:'external'}];
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('es-PA',{style:'currency',currency:'USD'}).format(n),cart=new Map();
const delivery=p=>!p.stock?'Sin entrega disponible':p.origin==='local'?'Local · 2–3 días (ficticio)':'Externo · 10–15 días (ficticio)';
for(const d of [...new Set(catalog.map(p=>p.department))]){const o=document.createElement('option');o.value=d;o.textContent=d;$('#department').append(o);}
function card(p,i){const a=document.createElement('article');a.className='card';a.innerHTML='<img src="assets/product-'+p.id+'.svg" width="240" height="240" alt="Ilustración ficticia: '+p.name+'" loading="'+(i<4?'eager':'lazy')+'"><h3><button class="more" data-detail="'+p.id+'">'+p.name+'</button></h3><p class="price">'+money(p.price)+'</p><p>'+(p.stock?'Disponible · ficticio':'Agotado')+'</p><p class="delivery">'+delivery(p)+'</p><button data-add="'+p.id+'" '+(p.stock?'':'disabled')+'>'+(p.variants?'Elegir variante':'Añadir al carrito')+'</button>';return a;}
function render(){const q=$('#q').value.trim().toLocaleLowerCase('es'),d=$('#department').value,s=$('#stock').value;const list=catalog.filter(p=>(!q||p.name.toLocaleLowerCase('es').includes(q))&&(!d||p.department===d)&&(!s||(s==='available'?p.stock>0:p.stock===0)));$('#products').replaceChildren(...list.map(card));$('#results').textContent=list.length?list.length+' productos de demostración':'No encontramos coincidencias. Limpia los filtros o prueba otra búsqueda.';}
function detail(id){const p=catalog.find(p=>p.id===id);$('#detail').innerHTML='<h2 id="detail-title">'+p.name+'</h2><img class="detail-image" src="assets/product-'+p.id+'.svg" width="240" height="240" alt="Ilustración ficticia"><p>'+money(p.price)+'</p><p>Producto ficticio. No está a la venta.</p><p>'+delivery(p)+'</p>'+(p.variants?'<label>Acabado<select id="variant">'+p.variants.map(v=>'<option>'+v+'</option>').join('')+'</select></label>':'')+'<p>Condiciones y devoluciones pendientes de validación.</p><button id="detail-add" '+(p.stock?'':'disabled')+'>Añadir al carrito</button>';$('#detail-add').onclick=()=>add(id,$('#variant')?.value||'');$('#product-dialog').showModal();}
function add(id,variant=''){const p=catalog.find(p=>p.id===id);if(!p.stock)return;if(p.variants&&!variant){detail(id);return;}const key=id+':'+variant,item=cart.get(key);if((item?.qty||0)>=p.stock){$('#results').textContent='Disponibilidad ficticia alcanzada.';return;}cart.set(key,{id,variant,qty:(item?.qty||0)+1});renderCart();$('#results').textContent=p.name+' añadido al carrito.';if($('#product-dialog').open)$('#product-dialog').close();}
function renderCart(){let total=0,count=0;const origins=new Set();$('#cart-items').replaceChildren();for(const [key,item] of cart){const p=catalog.find(p=>p.id===item.id);total+=p.price*item.qty;count+=item.qty;origins.add(p.origin);const row=document.createElement('div');row.className='cart-row';const title=document.createElement('strong');title.textContent=p.name+(item.variant?' · '+item.variant:'');const info=document.createElement('p');info.textContent=item.qty+' × '+money(p.price)+' · '+delivery(p);row.append(title,info);for(const [label,delta] of [['Reducir',-1],['Aumentar',1],['Quitar',-item.qty]]){const btn=document.createElement('button');btn.textContent=label;btn.setAttribute('aria-label',label+': '+p.name+' '+item.variant);btn.disabled=delta===1&&item.qty>=p.stock;btn.onclick=()=>{item.qty+=delta;if(item.qty<=0)cart.delete(key);renderCart();};row.append(btn);}$('#cart-items').append(row);}$('#count').textContent=count;$('#total').textContent=count?'Total productos: '+money(total)+'. Envío sin calcular.':'Tu carrito está vacío.';$('#mixed').hidden=origins.size<2;}
$('#products').addEventListener('click',e=>{const btn=e.target.closest('button');if(btn?.dataset.detail)detail(Number(btn.dataset.detail));if(btn?.dataset.add)add(Number(btn.dataset.add));});$('#search').onsubmit=e=>e.preventDefault();$('#q').oninput=render;$('#department').onchange=render;$('#stock').onchange=render;$('#reset').onclick=()=>{$('#q').value='';$('#department').value='';$('#stock').value='';render();};$('#cart-open').onclick=()=>$('#cart-dialog').showModal();document.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>document.getElementById(btn.dataset.close).close());render();renderCart();
